style.css:
/* Hiccstrid Aesthetic - Universal */
@namespace url(http://www.w3.org/1999/xhtml);

/* Apply to all sites */
@-moz-document regexp(".*") {
/* Background */
  body, html {
    background-image: url("https://i.imgur.com/3zT9QzY.jpg"); /* Hiccup & Toothless flying */
    background-size: cover;
    background-position: center;
    background-attachment: fixed;
    color: #e0e0e0; /* soft text for readability */
    font-family: 'Quicksand', sans-serif;
  }

  /* Links */
  a {
    color: #6bc4ff !important;
    text-decoration: none !important;
    transition: color 0.3s;
  }

  a:hover {
    color: #ffad6b !important;
  }

  /* Containers / Boxes */
  div, section, article {
    background-color: rgba(0, 0, 0, 0.4) !important;
    border-radius: 10px;
    padding: 5px;
    margin: 2px;
    transition: all 0.3s;
  }

  div:hover, section:hover, article:hover {
    background-color: rgba(0, 0, 0, 0.6) !important;
    box-shadow: 0 0 15px #6bc4ff;
    transform: scale(1.01);
  }

  /* Buttons */
  button {
    background-color: rgba(107,196,255,0.3) !important;
    color: #fff !important;
    border: 1px solid #6bc4ff !important;
    border-radius: 8px !important;
    transition: 0.2s;
  }

  button:hover {
    background-color: rgba(107,196,255,0.6) !important;
    box-shadow: 0 0 12px #6bc4ff;
    cursor: pointer;
  }

  /* Scrollbar (optional aesthetic touch) */
  ::-webkit-scrollbar {
    width: 12px;
  }

  ::-webkit-scrollbar-track {
    background: rgba(0,0,0,0.3);
    border-radius: 10px;
  }

  ::-webkit-scrollbar-thumb {
    background-color: #6bc4ff;
    border-radius: 10px;
    border: 2px solid rgba(0,0,0,0.2);
  }
}
